/**
 * @name XML External Entity (XXE) injection in BeautifulSoup
 * @description Parsing untrusted XML with external entity expansion enabled can lead to file disclosure, SSRF, or denial of service
 * @kind path-problem
 * @problem.severity error
 * @id py/xxe-beautifulsoup
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XxeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is BeautifulSoup constructor with XML content
    exists(API::CallNode call |
      call = API::moduleImport("bs4").getMember("BeautifulSoup").getACall() and
      sink = call.getArg(0)
    )
  }
}

module XxeFlow = TaintTracking::Global<XxeConfig>;
import XxeFlow::PathGraph

from XxeFlow::PathNode source, XxeFlow::PathNode sink
where XxeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XML content from $@ flows into BeautifulSoup constructor.", source.getNode(), "user input"

/**
 * @name XSS via HTML attribute injection in BeautifulSoup
 * @description User input flowing into HTML attributes that could execute JavaScript
 * @kind path-problem
 * @problem.severity high
 * @id py/xss-beautifulsoup-attributes
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XssAttributeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is setting HTML attributes via BeautifulSoup API
    exists(API::CallNode call |
      // Tag.__setitem__ for setting attributes
      call = API::moduleImport("bs4.element").getMember("Tag").getMember("__setitem__").getACall() and
      sink = call.getArg(1)
    ) or
    exists(API::CallNode call |
      // Tag.__setattr__ or direct attribute assignment
      call = API::moduleImport("bs4.element").getMember("Tag").getMember("__setattr__").getACall() and
      sink = call.getArg(1)
    )
  }
}

module XssAttributeFlow = TaintTracking::Global<XssAttributeConfig>;
import XssAttributeFlow::PathGraph

from XssAttributeFlow::PathNode source, XssAttributeFlow::PathNode sink
where XssAttributeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User input from $@ flows into HTML attribute assignment.", source.getNode(), "user input"

