/**
 * @name Path traversal in file operations
 * @description Untrusted input flowing to file operations can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal-beautifulsoup
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File operations that could be vulnerable to path traversal
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "stat", "chmod", "chown"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("os.path").getMember(["join", "exists", "isdir", "isfile"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@ flows to file operation.", source.getNode(), "user input"

/**
 * @name Cross-Site Scripting (XSS) via BeautifulSoup attributes
 * @description User-controlled data flowing to HTML attributes or content could lead to XSS
 * @kind path-problem
 * @problem.severity error
 * @id py/xss-beautifulsoup
 * @tags security
 *        external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module XssConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is setting HTML attributes or content that could lead to XSS
    exists(API::CallNode call |
      // Setting tag attributes
      call = API::moduleImport("bs4").getMember("Tag").getMember("__setitem__").getACall() and
      sink = call.getArg(1)
    ) or
    exists(API::CallNode call |
      // Setting tag string content
      call = API::moduleImport("bs4").getMember("Tag").getMember(["append", "insert", "insert_before", "insert_after"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      // Setting NavigableString
      call = API::moduleImport("bs4").getMember("NavigableString").getACall() and
      sink = call.getArg(0)
    )
  }
}

module XssFlow = TaintTracking::Global<XssConfig>;
import XssFlow::PathGraph

from XssFlow::PathNode source, XssFlow::PathNode sink
where XssFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data from $@ flows to HTML attribute/content that could lead to XSS.", source.getNode(), "user input"
